use crate::{BitReader, Error};

// Wire codewords indexed by coefficient order, then signed index + 8.
const WORDS: [[u16; 16]; 8] = [
    [
        4053, 1012, 507, 127, 30, 0, 1, 2, 2, 3, 6, 14, 62, 252, 2027, 8105,
    ],
    [
        15360, 7681, 3841, 961, 241, 61, 14, 2, 2, 3, 0, 6, 31, 121, 481, 1921,
    ],
    [
        27136, 27137, 3393, 425, 107, 52, 12, 7, 0, 2, 27, 213, 849, 1697, 6785, 27138,
    ],
    [
        8708, 8709, 8710, 1089, 273, 137, 35, 5, 0, 3, 9, 16, 69, 545, 8711, 4352,
    ],
    [
        4100, 4101, 4102, 257, 65, 17, 5, 0, 1, 3, 9, 33, 129, 513, 4103, 2048,
    ],
    [
        8272, 8273, 2069, 516, 128, 65, 17, 5, 0, 3, 9, 33, 259, 1035, 8274, 8275,
    ],
    [
        13312, 13313, 3329, 833, 209, 53, 12, 2, 0, 7, 27, 105, 417, 1665, 13314, 13315,
    ],
    [
        10490, 2625, 657, 165, 83, 21, 4, 3, 10497, 0, 11, 40, 329, 1313, 10498, 10499,
    ],
];
const LENGTHS: [[u8; 16]; 8] = [
    [12, 10, 9, 7, 5, 3, 3, 3, 2, 3, 3, 4, 6, 8, 11, 13],
    [15, 14, 13, 11, 9, 7, 5, 3, 2, 2, 2, 4, 6, 8, 10, 12],
    [15, 15, 12, 9, 7, 6, 4, 3, 1, 2, 5, 8, 10, 11, 13, 15],
    [14, 14, 14, 11, 9, 8, 6, 3, 1, 2, 4, 5, 7, 10, 14, 13],
    [14, 14, 14, 10, 8, 6, 4, 2, 1, 3, 5, 7, 9, 11, 14, 13],
    [14, 14, 12, 10, 8, 7, 5, 3, 1, 2, 4, 6, 9, 11, 14, 14],
    [14, 14, 12, 10, 8, 6, 4, 2, 1, 3, 5, 7, 9, 11, 14, 14],
    [14, 12, 10, 8, 7, 5, 3, 2, 14, 1, 4, 6, 9, 11, 14, 14],
];

pub(super) fn read_index(reader: &mut BitReader<'_>, order: usize) -> Result<i8, Error> {
    let mut word = 0;
    for length in 1..=15 {
        word = (word << 1) | reader.read(1)? as u16;
        if let Some(index) =
            (0..16).find(|&i| LENGTHS[order][i] == length && WORDS[order][i] == word)
        {
            return Ok(index as i8 - 8);
        }
    }
    Err(Error::Invalid("TNS codeword"))
}
